        S_G1      = 4'd5,
        S_G_WAIT2 = 4'd6,
        G_PERM_1  = 4'd7,
        G_PERM_0  = 4'd8
    } state_t;

    state_t state, next_state;

    // Synchronous active-low reset
    always_ff @(posedge clk) begin
        if (!resetn) begin
            state <= S_A;
        end else begin
            state <= next_state;
        end
    end

    // Next state and output logic
    always_comb begin
        next_state = state;
        f = 1'b0;
        g = 1'b0;

        case (state)
            S_A: begin
                f = 1'b0;
                g = 1'b0;
                if (resetn) begin
