                end else begin
                    next_state = X_NONE;
                end
            end

            S_G1: begin
                f = 1'b0;
                g = 1'b1;
                if (y) begin
                    next_state = G_PERM_1;
                end else begin
                    next_state = S_G_WAIT2;
                end
            end

